const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [[[-92.5, 49.5],
      [-92.5, 41.0],
      [-75.5, 41.0],
      [-75.5, 49.5]]], null, false);

  const date = '2016-02-11';
  const endDate = '2016-02-12'; // One day after to ensure the target date is included

  // 2. Data Acquisition & Check
  // Using MODIS Terra Surface Reflectance (MOD09GA) for daily coverage and cloud state information.
  // The 'cloud_state' band has values: 0=clear, 1=cloudy, 2=mixed, 3=not set/fill.
  const collection = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(date, endDate)
    .filterBounds(geometry);

  const imageCount = await collection.size().getInfo();
  console.log(`Images found for ${date}: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No MODIS images found for the specified date and location.");
    console.log("C1");
    return;
  }

  // Get the first image (MODIS is daily, so usually one relevant image per day/location)
  const image = ee.Image(collection.first());

  // 3. Processing: Identify cloudy pixels
  // Define what constitutes a cloudy pixel based on 'cloud_state' band
  // cloud_state values: 0 = Clear, 1 = Cloudy, 2 = Mixed, 3 = Not Set / Fill
  // We consider 1 (Cloudy) and 2 (Mixed) as indicating cloud presence.
  const cloudy = image.select('cloud_state').eq(1).or(image.select('cloud_state').eq(2));

  // Calculate the total number of pixels within the geometry that are not 'Not Set / Fill' (value 3)
  // And the number of cloudy pixels.
  const totalPixels = image.select('cloud_state').neq(3).reduceRegion({
    reducer: ee.Reducer.sum(), // Use sum with boolean image to count valid (non-fill) pixels
    geometry: geometry,
    scale: 500, // MODIS resolution
    maxPixels: 1e9,
    tileScale: 16
  }).get('cloud_state');

  const cloudyPixels = cloudy.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9,
    tileScale: 16
  }).get('cloud_state');

  const totalPixelsValue = await totalPixels.getInfo();
  const cloudyPixelsValue = await cloudyPixels.getInfo();

  console.log(`Total valid pixels in region: ${totalPixelsValue}`);
  console.log(`Cloudy pixels in region: ${cloudyPixelsValue}`);

  // 4. Validation & Final Answer
  if (totalPixelsValue === null || cloudyPixelsValue === null) {
    console.log("C3"); // Calculation returned null
    return;
  }

  if (totalPixelsValue === 0) {
    console.log("No valid pixels remain for analysis after filtering (could be entirely 'Not Set/Fill').");
    console.log("C2");
    return;
  }

  // Check if any cloudy pixels are present
  if (cloudyPixelsValue > 0) {
    console.log("A"); // Yes, clouds are present
  } else {
    console.log("B"); // No, clouds are not present
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
